// Hide/show nav on scroll direction
  (function(){
    let lastY = window.scrollY;
    const nav = document.getElementById('topnav');
    window.addEventListener('scroll', () => {
      const y = window.scrollY;
      if (y > lastY && y > 120) nav.classList.add('hide');
      else nav.classList.remove('hide');
      lastY = y;
    }, {passive:true});
  })();

  // Mobile hamburger menu toggle
  (function(){
    const toggle = document.getElementById('navToggle');
    const links = document.getElementById('navLinks');
    if (!toggle || !links) return;
    toggle.addEventListener('click', () => {
      const isOpen = links.classList.toggle('open');
      toggle.classList.toggle('open', isOpen);
      toggle.setAttribute('aria-expanded', String(isOpen));
    });
    links.querySelectorAll('a').forEach(a => {
      a.addEventListener('click', () => {
        links.classList.remove('open');
        toggle.classList.remove('open');
        toggle.setAttribute('aria-expanded', 'false');
      });
    });
  })();

  // Objectives accordion
  document.querySelectorAll('.obj-card').forEach(card => {
    card.addEventListener('click', () => {
      const wasActive = card.classList.contains('active');
      document.querySelectorAll('.obj-card').forEach(c => c.classList.remove('active'));
      if (!wasActive) card.classList.add('active');
    });
  });

  // Before/after compare slider
  (function(){
    const range = document.getElementById('compareRange');
    const after = document.getElementById('afterImg');
    const handle = document.getElementById('handle');
    function update(v){
      after.style.clipPath = `inset(0 0 0 ${v}%)`;
      handle.style.left = v + '%';
    }
    range.addEventListener('input', e => update(e.target.value));
    update(50);

    // colourway toggle
    const imgs = {
      dark: { before: 'data:image/jpeg;base64,', after: 'data:image/jpeg;base64,' },
      mint: { before: 'data:image/jpeg;base64,', after: 'data:image/jpeg;base64,' }
    };
    document.querySelectorAll('#colorToggle button').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('#colorToggle button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const c = btn.dataset.c;
        document.getElementById('beforeImg').src = imgs[c].before;
        document.getElementById('afterImg').src = imgs[c].after;
      });
    });
  })();

  // Appeal toggle
  document.querySelectorAll('#appealToggle button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('#appealToggle button').forEach(b => b.classList.remove('active'));
      document.querySelectorAll('.appeal-panel').forEach(p => p.classList.remove('active'));
      btn.classList.add('active');
      document.querySelector(`.appeal-panel[data-p="${btn.dataset.a}"]`).classList.add('active');
    });
  });

  // Animate sense bars on scroll into view
  (function(){
    const rows = document.querySelectorAll('.sense-row');
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting){
          const fill = en.target.querySelector('.sbar-fill');
          fill.style.width = en.target.dataset.w + '%';
          io.unobserve(en.target);
        }
      });
    }, {threshold:0.4});
    rows.forEach(r => io.observe(r));
  })();

  // AR phone preview: swap the interactive 3D keyboard model by colourway
  (function(){
    const modelSources = {
      mint: 'data:model/gltf-binary;base64,',
      navy: 'data:model/gltf-binary;base64,'
    };
    const viewer = document.getElementById('arModel');
    const swatches = document.querySelectorAll('#colorPicker .swatch');
    if (!viewer || !swatches.length) return;
    swatches.forEach(btn => {
      btn.addEventListener('click', () => {
        swatches.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const next = modelSources[btn.dataset.model];
        if (next) viewer.setAttribute('src', next);
      });
    });
  })();
